/* Figure catalog (see catalog.h). The TSV is generated by tools/build_data.py from the
 * figure list RPCS3 ships for its Infinity base (1.0, 2.0 and 3.0 figures, discs and pieces).
 * Copyright (C) 2026 SpiderNic96. SPDX-License-Identifier: GPL-3.0-or-later */
#include "catalog.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAT_MAX 512
static cat_entry g_cat[CAT_MAX];
static int g_n;

int catalog_load(const char *path) {
    FILE *f = fopen(path, "r");
    g_n = 0;
    if (!f) return 0;
    char ln[512];
    while (fgets(ln, sizeof ln, f) && g_n < CAT_MAX) {
        if (ln[0] == '#' || ln[0] == '\n') continue;
        char *nl = strpbrk(ln, "\r\n");
        if (nl) *nl = 0;
        char *c[8] = {0};
        int k = 0;
        c[k++] = ln;
        for (char *p = ln; *p && k < 8; p++) if (*p == '\t') { *p = 0; c[k++] = p + 1; }
        if (k < 4) continue;
        char *tab = strchr(c[k - 1], '\t');   /* ignore any later columns */
        if (tab) *tab = 0;
        cat_entry *e = &g_cat[g_n];
        e->id = (uint32_t)strtoul(c[0], 0, 10);
        e->series = atoi(c[1]);
        e->kind = c[2][0];
        snprintf(e->name, sizeof e->name, "%s", c[3]);
        snprintf(e->group, sizeof e->group, "%s", k > 4 ? c[4] : "");
        snprintf(e->aka, sizeof e->aka, "%s", k > 7 ? c[7] : "");
        e->foot[0] = e->foot[1] = e->foot[2] = 0;
        if (k > 6) sscanf(c[6], "%f,%f,%f", &e->foot[0], &e->foot[1], &e->foot[2]);
        e->fx = k > 5 && !strcmp(c[5], "saber") ? FX_SABER : k > 5 && !strcmp(c[5], "glow") ? FX_GLOW : FX_NONE;
        if (e->id) g_n++;
    }
    fclose(f);
    return g_n;
}

int catalog_count(void) { return g_n; }
const cat_entry *catalog_at(int i) { return (i >= 0 && i < g_n) ? &g_cat[i] : 0; }

const cat_entry *catalog_find(uint32_t id) {
    for (int i = 0; i < g_n; i++) if (g_cat[i].id == id) return &g_cat[i];
    return 0;
}

char catalog_kind_of(uint32_t id) {
    const cat_entry *e = catalog_find(id);
    if (e) return e->kind;
    switch (id / 1000000) {
    case 1: return K_FIGURE;
    case 2: return K_PIECE;
    case 3: return K_ROUND;
    case 4: return K_HEX;
    default: return 0;
    }
}

int catalog_series_of(uint32_t id) {
    const cat_entry *e = catalog_find(id);
    return (e && e->series >= 1 && e->series <= 3) ? e->series : 1;
}

const char *catalog_name(uint32_t id, char *buf, int n) {
    const cat_entry *e = catalog_find(id);
    if (e) snprintf(buf, (size_t)n, "%s", e->name);
    else snprintf(buf, (size_t)n, "Figure #%u", id);
    return buf;
}

int catalog_slot_ok(uint32_t id, int slot) {
    if (slot < 0 || slot > 8) return 0;
    switch (catalog_kind_of(id)) {
    case K_FIGURE: return slot == 3 || slot == 6;
    case K_ROUND:  return slot == 4 || slot == 5 || slot == 7 || slot == 8;
    case K_PIECE:  return slot == 0;   /* the play set spot: one piece at a time */
    case K_HEX:    return slot <= 2;
    default:       return 1;   /* unknown dumps: let the user decide */
    }
}

const char *catalog_kind_label(char kind) {
    switch (kind) {
    case K_FIGURE: return "Character";
    case K_PIECE:  return "Play Set / Toy Box piece";
    case K_ROUND:  return "Power Disc";
    case K_HEX:    return "Hex Power Disc";
    default:       return "Unknown";
    }
}

const char *catalog_group(uint32_t id) {
    const cat_entry *e = catalog_find(id);
    return e ? e->group : "";
}

int catalog_fx(uint32_t id) {
    const cat_entry *e = catalog_find(id);
    return e ? e->fx : FX_NONE;
}

int catalog_foot(uint32_t id, float *cx, float *by, float *bw) {
    const cat_entry *e = catalog_find(id);
    if (e && e->foot[2] > 0.01f) { *cx = e->foot[0]; *by = e->foot[1]; *bw = e->foot[2]; return 1; }
    *cx = 0.5f; *by = 0.96f; *bw = 0.6f;
    return 0;
}
